package engine.llm

/** Ephemeral row ids map back to immutable Utterance ids. No metadata is generated by the LLM. */
internal object BatchFormat {
    private val row = Regex("^\\[(\\d+)\\][ \\t]?(.*)$")
    data class Decoded(val rows: Map<Int, String>, val malformed: Boolean)

    fun encode(texts: List<String>): String = texts.mapIndexed { i, text ->
        "[$i] " + text.replace('\r', ' ').replace('\n', ' ')
    }.joinToString("\n")

    fun decode(answer: String, count: Int): Decoded {
        val rows = mutableMapOf<Int, String>()
        val duplicate = mutableSetOf<Int>()
        var malformed = false
        for (line in answer.lineSequence().filter { it.isNotBlank() }) {
            val match = row.matchEntire(line.trim())
            if (match == null) { malformed = true; continue }
            val id = match.groupValues[1].toIntOrNull()
            if (id == null || id !in 0 until count) { malformed = true; continue }
            if (id in rows || id in duplicate) {
                malformed = true; duplicate.add(id); rows.remove(id)
            } else rows[id] = match.groupValues[2]
        }
        return Decoded(rows, malformed || rows.size != count)
    }
}
